/* honestporn app-shell service worker.
 *
 * Filename is historical — js/torrent.js hardcodes register('/sw.min.js'), so the
 * name is load-bearing even though this file is now hand-written and unminified.
 *
 * Two jobs, in this order:
 *   1. cache the app shell so a repeat visit paints without waiting on the network
 *   2. hand everything else to the VENDORED WebTorrent 3.x streaming bridge, which is
 *      importScripts()'d PRISTINE at the bottom of this file
 *
 * WHY the fall-through style: multiple fetch listeners are allowed and the FIRST one
 * to call respondWith() wins. Ours is registered before the import, so ours runs first
 * and simply `return`s — without responding — for anything it does not own. The vendored
 * listener then sees the event untouched. Never respondWith() a "pass through" fetch here;
 * that would route torrent range traffic through us and break playback.
 */

var VERSION = 'hp-shell-8c6beac'; /* bump this string to hard-flush every client's shell cache */

/* Exactly what index.html pulls on a cold load. Derived from its <script defer> tags —
 * keep in sync when a tag is added. Deliberately NO vendor/ entries: hls.js, webtorrent
 * and the ~87MB whisper/transformers blobs are lazy and must never be precached. */
var SHELL = [
  './', 'index.html', 'style.css', 'assets/banner.svg', 'js/errlog.js',
  'js/addons.js', 'js/registry.js', 'js/wallview.js', 'js/app.js', 'js/torrent.js',
  'js/player.js', 'js/netmon.js', 'js/dev.js', 'js/whisper-engine.js',
  'js/subs-mp4-window.js', 'js/subs-ts-window.js', 'js/subs-hls-map.js',
  'js/subs-audio-source.js', 'js/subs-autosync.js', 'js/whisper-tiny.js'
];

self.addEventListener('install', function (e) {
  /* Per-entry add() with a swallow, NOT addAll(): addAll is atomic, so one 404 (a
   * renamed script, a half-synced deploy) would fail the whole install and leave the
   * site with no worker at all. A partial shell is strictly better than none. */
  e.waitUntil(caches.open(VERSION).then(function (c) {
    return Promise.all(SHELL.map(function (u) { return c.add(new Request(u, { cache: 'no-cache' })).catch(function () {}); }));
  }).then(function () { return self.skipWaiting(); }));
});

self.addEventListener('activate', function (e) {
  e.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.map(function (k) { return k === VERSION ? null : caches.delete(k); }));
  }).then(function () { return self.clients.claim(); }));
});

function put(req, res) {
  if (res && res.ok) { var copy = res.clone(); caches.open(VERSION).then(function (c) { c.put(req, copy); }); }
  return res;
}

self.addEventListener('fetch', function (event) {
  var req = event.request;
  if (req.method !== 'GET') return;
  var url = new URL(req.url);
  if (url.origin !== self.location.origin) return;      /* addon APIs, posters, CDNs: not ours */
  if (url.pathname.indexOf('/webtorrent/') !== -1) return; /* the vendored bridge owns these */
  if (req.headers.has('range')) return;                 /* never intercept ranged media */

  /* THE ESCAPE HATCH — do not remove. js/registry.js polls verified_sources.md and
   * js/dev.js polls the core files, both with fetch(..., {cache:'no-store'}). That flag
   * survives into the SW fetch event (verified in Chrome), so honouring it here is what
   * keeps the live registry watch and devmode hot-reload seeing the network, never us. */
  if (req.cache === 'no-store' || req.cache === 'reload') return;

  if (url.pathname.indexOf('/vendor/') === 0) return;   /* big lazy libs + ~87MB whisper: browser HTTP cache only */

  /* The registry file is the product's honesty guarantee: never serve it stale.
   * Network-first, cache only as an offline floor. */
  if (/\/verified_sources\.md$/.test(url.pathname)) {
    event.respondWith(fetch(req).then(function (r) { return put(req, r); })
      .catch(function () { return caches.match(req); }));
    return;
  }

  /* App shell: stale-while-revalidate — instant paint from cache, fresh copy fetched in
   * the background so a redeploy self-heals within one load with no VERSION bump. */
  event.respondWith(caches.match(req).then(function (hit) {
    var net = fetch(req, { cache: 'no-cache' }).then(function (r) { return put(req, r); }).catch(function () { return hit; });
    if (hit) event.waitUntil(net); /* keep the worker alive until the refresh lands */
    return hit || net;
  }));
});

/* Vendored WebTorrent 3.x streaming bridge, unmodified. MUST stay last: its fetch
 * listener is the fall-through for everything we declined above. */
importScripts('vendor/webtorrent-sw.min.js');
